expressionInfos.expression:
var status = $feature.Status;

if (status == 0) {
 return "0: Disabled";
}

var static_messages = [
 "1: Inserted/Updated feature",
 "2: Deleted feature",
 "4: Modified objects",
 "8: Feature error",
 "16: Object error",
 "32: Subnetwork Error"
];

var statuses = [];
var mask = 1;
var i = 0;

for (var j = 0; j < 6; j++) {
 if (mask > status) break;
 if ((status & mask) > 0) {
 statuses[i++] = static_messages[j];
 }
 mask *= 2;
}

return Concatenate(statuses, '\n');

